#!/usr/bin/env python3
"""Restore one missing local entrypoint, byte-for-byte, without processing.
Source: saved IPHONE_888_POKRETAC.py, 2026-09-13, 11496 bytes.
Effects: exclusively create /root/IPHONE_888_POKRETAC.py (mode 0600), fsync,
read back, then invoke its reviewed no-argument help path in isolated Python.
Existing targets are never overwritten. No AI runner, services or data changes.
An interrupted partial creation is reported as a conflict on the next attempt;
it is not automatically overwritten, deleted, or executed.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import signal
import stat
import subprocess
import sys

ROOT = Path('/root/FREYA_RAD_888')
TARGET = '/root/IPHONE_888_POKRETAC.py'
PIN = 'be80f70a7ecdbace39a9a2d375eff70858b007ea28fb54495756bd74ffcbb46b'
PAYLOAD_B64 = ''
POLICY = 'PROTOCOL=888\nKORAK=6\nACTION=BURY\nDELETE_EXECUTED=NO\nCOPY_TO_CVOR=NO\nCOPY_TO_ULAZ=NO\n1=TITAN_SUPREME_DASHBOARD_v35_2.xlsx (254 MB) — Debian, ne iSH\n2=zlato_md Data Room v6.3 (3161) — ne fioka\n3=TITAN_FORENSIC_REVISION_MASTER v2-v33\n4=inventory / mutation_generator / hidra_map CSV\n5=cp recovery -> FREYA_IPHONE_ISH_NODE_888\n6=EXACT_DUPLICATES, UNIFIED_RUNNER, MAGNUS\n7=18 agenata kao procesi\nHUMAN_GATE=YES\nFAIL_CLOSED=YES\n'
IDENTITY = {
    'protocol':'888', 'version':1,
    'engine_sha256':'01cd6ee9c07d76f2b974b655791c4bcb8426e128bdb29ca221cfcce502064525',
    'document_sha256':'8236c31e63747752248df5c70c13e7d3786dd53336387bb115a63fef5cc8f64d',
    'validator_sha256':'97a77c63383646e81e56e2b5712714778dee6e4e9235b0d71e92cd1431a67db1'
}
CREATED = False
VERIFIED = False

def out(event, **fields):
    print(json.dumps(dict(event=event, **fields),ensure_ascii=True),flush=True)

def require(condition, code):
    if not condition:
        raise RuntimeError(code)

def read(path, limit=131072):
    path = Path(path)
    fd = os.open('/',os.O_RDONLY|os.O_DIRECTORY)
    try:
        for part in path.parts[1:-1]:
            nxt=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
            os.close(fd)
            fd=nxt
        source=os.open(path.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=fd)
    finally:
        os.close(fd)
    with os.fdopen(source,'rb') as f:
        a=os.fstat(f.fileno())
        require(stat.S_ISREG(a.st_mode) and a.st_size<=limit,'SOURCE_TYPE_OR_SIZE')
        data=f.read(a.st_size+1)
        b=os.fstat(f.fileno())
    require(len(data)==a.st_size and (a.st_ino,a.st_size,a.st_mtime_ns,a.st_ctime_ns)==
            (b.st_ino,b.st_size,b.st_mtime_ns,b.st_ctime_ns),'SOURCE_CHANGED_DURING_READ')
    return data

def alarm(*args):
    raise RuntimeError('TIME_LIMIT')

def main():
    global CREATED, VERIFIED
    signal.signal(signal.SIGALRM,alarm)
    signal.alarm(30)
    out('HEADER',batch='IPHONE_R8_004_RESTORE_LOCAL_ENTRYPOINT_888',protocol=888,
        effect='CREATE_ONE_MISSING_LOCAL_ENTRYPOINT',target=TARGET,
        network_calls=0,business_processing=False)
    require('ish' in os.uname().release.lower() and os.geteuid()==0 and
            Path('/etc/alpine-release').is_file(),'WRONG_CONTEXT')
    require(ROOT.resolve(strict=True)==ROOT and ROOT.is_dir(),'ROOT_CHANGED')
    require(json.loads(read(ROOT/'IDENTITY.json',4096))==IDENTITY,'IDENTITY_CHANGED')
    require(read(ROOT/'NE_DIRATI.txt',4096)==POLICY.encode('utf-8'),'POLICY_CHANGED_REVIEW_REQUIRED')
    for name,key in [('ENGINE.py','engine_sha256'),('document_processor.py','document_sha256'),
                     ('financial_validator_v2_888.py','validator_sha256')]:
        require(hashlib.sha256(read(ROOT/'CODE'/name)).hexdigest()==IDENTITY[key],
                'DEPENDENCY_CHANGED')
    payload=base64.b64decode(PAYLOAD_B64,validate=True)
    require(len(payload)==11496 and hashlib.sha256(payload).hexdigest()==PIN,'PAYLOAD_DIGEST')
    compile(payload,TARGET,'exec')
    parent=os.open('/root',os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        storage=os.fstatvfs(parent)
        require(storage.f_bavail*storage.f_frsize>=1024*1024,'INSUFFICIENT_WORKING_SPACE')
        try:
            fd=os.open('IPHONE_888_POKRETAC.py',
                       os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=parent)
        except FileExistsError:
            require(hashlib.sha256(read(TARGET)).hexdigest()==PIN,'EXISTING_TARGET_CONFLICT')
            action='ALREADY_PRESENT_IDENTICAL'
        else:
            CREATED=True
            with os.fdopen(fd,'wb') as f:
                f.write(payload)
                f.flush()
                os.fsync(f.fileno())
            action='RESTORED'
    finally:
        os.close(parent)
    actual=read(TARGET)
    require(actual==payload,'RESTORED_READBACK_MISMATCH')
    VERIFIED=True
    out('RESTORE_RECEIPT',action=action,target=TARGET,bytes=len(actual),
        sha256=hashlib.sha256(actual).hexdigest(),readback='PASS',
        existing_files_overwritten=0,created_files=int(CREATED))
    result=subprocess.run([sys.executable,'-I','-S','-B',TARGET],
                          stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=8)
    expected='Pokreni sa --pokreni-888. Bez argumenta nema promjena.'
    require(result.returncode==0 and result.stdout.decode('utf-8').strip()==expected
            and not result.stderr,'NO_ARGUMENT_ENTRYPOINT_TEST_FAILED')
    require(read(TARGET)==payload,'TARGET_CHANGED_AFTER_HELP_TEST')
    out('FINAL',result='LOCAL_ENTRYPOINT_RESTORED_AND_HELP_TEST_PASS',
        scope='ONE_EXISTING_LOCAL_RUNNER',restoration_verified=True,
        no_argument_help_test='PASS',business_processing_executed=False,
        ai_runner_restored=False,network_calls=0,background_service_started=False,
        original_documents_modified=0,lock_modified=False,
        signal_end_to_end_acceptance='NOT_TESTED',
        next='RETURN_RECEIPT_FOR_BOUNDED_LOCAL_FUNCTION_TEST')
    signal.alarm(0)
    return 0

if __name__=='__main__':
    try:
        raise SystemExit(main())
    except (Exception,KeyboardInterrupt) as e:
        out('FINAL',result='HOLD',reason=str(e) if type(e) is RuntimeError else type(e).__name__,
            target_created_this_run=CREATED,target_readback_verified=VERIFIED,
            automatically_removed=False,automatically_overwritten=False,
            next='RETURN_OUTPUT_DO_NOT_EXECUTE_UNVERIFIED_TARGET')
        raise SystemExit(2)
